ault", "client_error", "tariff_terms", "service_quality", "fraud_suspicion", "info_request", "gratitude", "suggestion", "legal_regulatory", "unknown"]}, "criticality": {"type": "string", "enum": ["low", "medium", "high"]}, "tone": {"type": "string", "enum": ["neutral", "positive", "irritated", "angry", "sarcastic", "formal"]}, "flags": {"type": "array", "uniqueItems": true, "items": {"type": "string", "enum": ["churn_intent", "repeat", "sarcasm", "aggression", "mass_impact", "public", "rule_confirmed", "regulator_threat", "passive_aggression", "repeat_contact_7d", "red_word"]}}, "entities": {"type": "object", "additionalProperties": false, "properties": {"amount_rub": {"type": ["number", "null"]}, "operation_date_sim": {"type": ["string", "null"]}, "promo_code": {"type": ["string", "null"]}, "mentions": {"type": "array", "items": {"type": "string", "enum": ["churn", "court", "regulator", "fraud", "media", "competitor"]}}, "masked_card": {"type": ["string", "null"], "pattern": "^\\*{4} \\d{4}$"}}}, "churn_risk": {"type": "integer", "minimum": 0, "maximum": 100}, "confidence": {"type": "number", "minimum": 0, "maximum": 1}, "related_incident_ids": {"type": "array", "items": {"type": "integer"}, "description": "Кандидаты на связывание (из find_related_incidents)"}, "summary_ru": {"type": "string", "maxLength": 300}, "rationale_ru": {"type": "string", "minLength": 20, "maxLength": 1200, "description": "2–4 предложения, показываются CX и жюри"}, "language": {"type": "string", "default": "ru"}, "negativity": {"type": "integer", "minimum": 0, "maximum": 100, "description": "Уровень негатива текста 0–100 (BRD FR 1.2); копируется из normalization"}, "intents": {"type": "array", "uniqueItems": true, "items": {"type": "string", "enum": ["churn_threat", "refund_request", "complaint", "question", "public_shaming", "regulator_threat", "gratitude"], "description": "Намерения автора текста (ТЗ 7, BRD FR 1.2)"}}, "sentiment": {"type": "string", "enum": ["positive", "neutral", "negative"], "description": "Трёхклассная тональность (ДТЗ FR-2.1); сверяется с порогами negativity ≤33 / 34–66 / ≥67"}, "product_line": {"type": "string", "enum": ["deposits", "mortgage", "loans", "credit_cards", "debit_cards", "transfers_payments", "mobile_app", "investments", "insurance", "bonuses_subscription", "branches_service", "support", "business_banking", "atm_self_service", "fraud_security", "other"], "description": "[ЕТЗ FR-2.4] продуктовое направление"}, "product_line_confidence": {"type": "number", "minimum": 0, "maximum": 1}, "secondary_lines": {"type": "array", "maxItems": 2, "uniqueItems": true, "items": {"type": "string", "enum": ["deposits", "mortgage", "loans", "credit_cards", "debit_cards", "transfers_payments", "mobile_app", "investments", "insurance", "bonuses_subscription", "branches_service", "support", "business_banking", "atm_self_service", "fraud_security", "other"]}}, "signal_level": {"type": "string", "description": "[ЕТЗ FR-2.5] подпись уровня сигнала для кабинета"}, "problem_summary": {"type": "object", "additionalProperties": false, "required": ["problem", "severity", "suggested_team"], "description": "[ДТЗ FR-2.3] саммари проблемы ≤ 2 предложений (валидация числа предложений — в коде)", "properties": {"problem": {"type": "string", "minLength": 10, "maxLength": 300}, "severity": {"type": "string", "enum": ["low", "medium", "high", "critical"], "description": "problem_summary.severity (ДТЗ FR-2.3); low/medium/high = criticality, critical = high + признак обязательного HITL"}, "suggested_team": {"type": "string", "enum": ["team_cx", "team_deposits", "team_lending", "team_debit", "team_front", "team_processing", "team_notifications", "team_contact_center", "team_promo", "team_antifraud", "team_compliance", "team_branch_network"]}}}, "red_words": {"type": "array", "items": {"type": "string"}, "uniqueItems": true}}}, "rule_codes": {"type": "array", "minItems": 1, "items": {"type": "string"}, "description": "Правила, подтверждающие действие; без